import{_ as B,H as e,f as t,i as s}from"./chunks/framework.BH2BK_3i.js";const l=JSON.parse('{"title":"第十封信-阳光之下没什么新鲜事儿（中）","description":"","frontmatter":{},"headers":[],"relativePath":"去无方向的信/第十封信-阳光之下没什么新鲜事儿（中）.md","filePath":"去无方向的信/第十封信-阳光之下没什么新鲜事儿（中）.md","lastUpdated":1795542896000}'),i={name:"去无方向的信/第十封信-阳光之下没什么新鲜事儿（中）.md"};function p(a,E,n,A,o,F){return e(),t("div",null,[...E[0]||(E[0]=[s('<h1 id="第十封信-阳光之下没什么新鲜事儿-中" tabindex="-1">第十封信-阳光之下没什么新鲜事儿（中） <a class="header-anchor" href="#第十封信-阳光之下没什么新鲜事儿-中" aria-label="Permalink to &quot;第十封信-阳光之下没什么新鲜事儿（中）&quot;">​</a></h1><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/1.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/2.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/3.png" alt=""></a></p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/4.png" alt=""></a></p><p>生生：</p><p>你好哇。</p><p>我们现在好像已经知道在几种不同的天气下应该怎么设置相机了，感觉只要在有日光的环境下，应该就没什么问题了。但我说，我管那些基础的标准曝光参数叫“锚点参数”，只是基础的锚点而已。</p><p>为便于表述，我可以把锚点参数的定义再搞得具体一点：在某一基本恒定的光照条件下，当快门为 1/125s，ISO 为 ISO100 时，匹配相应的光圈，如果可以得到标准的曝光，那我们就认定这一组参数是这个光照条件下的锚点参数。</p><p>还记得这张照片儿吧？他又来了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%8E%BB%E6%97%A0%E6%96%B9%E5%90%91%E7%9A%84%E4%BF%A1/images/%25E7%25AC%25AC%25E5%258D%2581%25E5%25B0%2581%25E4%25BF%25A1-%25E9%2598%25B3%25E5%2585%2589%25E4%25B9%258B%25E4%25B8%258B%25E6%25B2%25A1%25E4%25BB%2580%25E4%25B9%2588%25E6%2596%25B0%25E9%25B2%259C%25E4%25BA%258B%25E5%2584%25BF%25EF%25BC%2588%25E4%25B8%25AD%25EF%25BC%2589/5.png" alt=""></a></p><p>这张照片儿的曝光参数是 [1/125s F8 ISO200]。</p><p>但这个参数并不是这个光照条件下的锚点参数。因为锚点参数，在我的定义里，需要满足快门是 1/125s 以及 ISO 是 ISO100，所以，我会定义这个光照条件下的锚点参数是 [1/125s F5.6ISO100]。ISO 从原来的 ISO200 降到了 ISO100，这样一来曝光就降了一档，但为了保证总曝光量不变，所以光圈要加大一档，从原来的 F8 变成了 F5.6。</p><p>到这儿，我们就必须得再来解决几个问题了，不然阳光十六法则就没法儿真正落地。</p><p>咱们一个一个来：</p><ol><li>什么是晴天？什么是多云？什么是阴天？什么是乌云压顶？</li></ol><p>我们经常会说“今天的阳光真好”这样的话，这是很主观的判断，如果我们想恰当地使用阳光十六法则，我们就必须要找出一个相对直观的标准，简单来说，我们分辨这个天气是不是这个天气的方法是：看影子。</p><p>影子边缘清晰且锋利，是晴天；影子边缘较清晰，是多云；影子边缘模糊不清，是阴天；没有影子，是大阴天或乌云压顶。</p><p>我们判断光线强度，看的不是我们眯眼睛的程度，我们看的不是光，而是影。</p><ol start="2"><li>晴天能不能不用 F16？多云能不能不用 F11？阴天能不能不用 F8？</li></ol><p>当然能，咱们拿多云举例。</p><p>今天多云，根据阳光十六法则，我们知道多云的锚点参数是 [1/125s F11 ISO100]，但现在我的拍摄目标是这样的：我需要拍一条正在发疯的疯狗，我希望可以拍得很清楚。</p><p>于是，我们的锚点参数就要开始变身了：</p><p>首先，快门要从 1/125s 变成 1/500s，尽可能速度快一点，毕竟狗疯了嘛，他的动作幅度会比较大。但因为主体只有一条狗，而且我怕被他咬，离他也有一定距离，所以即便他疯了，到处跑来跑去，我也不需要过于大的景深，适当有保证就行，所以我可以稍微把光圈扩大一档，从F11 变成 F8。</p><p>快门加快了两档，等于是减少了两档曝光，光圈增加了一档曝光，为了保证 (-2)+(+1)+(+1)=0，所以我的 ISO 要从 ISO100 变成 ISO200。</p><p>最终曝光参数：[1/500s F8 ISO200]</p><p>但现在情况变了，这条狗不光是自己瞎疯了，他还追着一群人咬，追得那群人满街疯跑……于是，锚点参数再次变身，但因为情况变了，所以刚才那个变体用不了了。</p><p>我们的快门速度还得是 1/500s，但光圈非但不能扩大，反而需要缩小，因为如果想把一帮人前前后后都拍清楚，保险起见，我们需要尽可能大的景深，所以光圈我们要选 F16。比对锚点参数，快门减了两档曝光 (1/125s→1/500s)，光圈减了一档曝光 (F11→F16)，为了保证 (-2)+(-1)+(+3)=0，我们需要把 ISO 值增大三档，设为 ISO800 (ISO100→ISO800)。</p><p>最终曝光参数：[1/500s F16 ISO800]</p><ol start="3"><li>晴天阴影里的锚点参数是多少？</li></ol><p>如果恪守规范的阳光十六法则，晴天阳光下和晴天阴影里差着四档曝光，也就是说，晴天阴影里的锚点参数是 [1/125s F4 ISO100]，但以我的经验，我觉得只差两档曝光，顶多三档曝光，所以，我认为晴天阴影里的锚点参数是 [1/125s F8 ISO100]。</p><p>当然，这还需要考虑你要拍的东西处于阴影里的什么位置，因为在阴影里，越靠近明暗分界线的东西肯定会越亮一点，基本常识。</p><p>说回来，用这个锚点拍出来的照片儿可能会稍微暗一点，但这样保证了景深，比较安全。</p><p>现在大家基本都拍数码照片儿，而且很多人都开始拍 RAW 图了，连手机都开始上 RAW 文件了，前期的原始照片儿稍微暗一点是没有问题的，因为后期分分钟就能拉回来，但如果因为景深浅了导致失焦，后期是救不回来的。</p><p>所以，前期的任务必须在前期完成。</p><p>至于什么是前期必须完成的任务，什么又是可以交给后期的，我们后面会细聊。</p><ol start="4"><li>锚点参数能达到什么效果？</li></ol><p>以我的经验，锚点参数并不能拍出曝光完全准确的照片儿，都会稍微暗一点点，但前期曝光准确本来就是没有必要的，甚至连“曝光准确”本来都是一个伪命题……前期暗一点点是最好的，前期的暗可能是因为你保全了速度，可能是因为你保全了景深，总之还是那句话，这些东西如果在前期没有权衡好，后期是救不回来的。</p><ol start="5"><li>晴天 F16 就一定行么？</li></ol><p>不行，有三个原因。</p><p>第一个原因是，F16 可以保证天空不过曝，如果在有大片天空的空场拍，没问题，但是，如果四周有建筑，有光线遮挡或甚至阴影，F16 不能保证建筑群之间的曝光……在这种场景下，我通常会增大一档光圈到 F11。</p><p>第二个原因是，随着季节不同，同是“阳光灿烂”，但光照强度有区别，夏天的阳光灿烂用F16，冬天的阳光灿烂用 F11，冬天阳光灿烂的建筑群之间，用 F8。</p><p>第三个原因是，拍摄主体的反光率不同，如果拍雪地和沙地，或者拍白色的东西，因为他们太容易反光了，有的时候他们甚至能比天空还要亮，那我们大概率会用到不常用的 F22，或者还是用 F16，但我们可以解放一档快门，从 1/125s 放到 1/250s。</p><p>这次我举了很多例子，但最后了，我必须提醒一点，即便有这么多例子，但举例是无法穷尽所有可能性的，所以请你一定再多自己思考一下下，拿着相机出门去试一试，争取可以做到举一反三反五反七八九。</p><p>阳光十六法则还没有说完，咱们下次继续聊。</p>',45)])])}const g=B(i,[["render",p]]);export{l as __pageData,g as default};
